using System;
using PX.Data;
using PX.Objects.PO;

namespace StudioB.Containers
{
    public class POOrderEntry_Extension : PXGraphExtension<POOrderEntry>
    {
        public static bool IsActive() => true;

        protected void _(Events.FieldDefaulting<POLine, POLineExt.usrExpArrivalDate> e)
        {
            if (e.Row == null) return;
            POOrder header = Base.Document.Current;
            if (header == null) return;
            POOrderExt headerExt = header.GetExtension<POOrderExt>();
            if (headerExt?.UsrExpArrivalDate != null)
            {
                e.NewValue = headerExt.UsrExpArrivalDate;
                e.Cancel = true;
            }
        }

        protected void _(Events.FieldUpdated<POOrder, POOrderExt.usrExpArrivalDate> e)
        {
            if (e.Row == null) return;
            DateTime? oldValue = (DateTime?)e.OldValue;
            DateTime? newValue = e.Row.GetExtension<POOrderExt>()?.UsrExpArrivalDate;
            if (newValue == null) return;
            if (oldValue == newValue) return;
            foreach (POLine line in Base.Transactions.Select())
            {
                POLineExt lineExt = line.GetExtension<POLineExt>();
                if (lineExt == null) continue;
                bool isInherited = lineExt.UsrExpArrivalDate == null || lineExt.UsrExpArrivalDate == oldValue;
                if (isInherited)
                {
                    lineExt.UsrExpArrivalDate = newValue;
                    Base.Transactions.Update(line);
                }
            }
        }
    }
}

using System;
using System.Collections.Generic;
using PX.Data;
using PX.Objects.IN;

namespace StudioB.Containers
{
    public class InventoryAllocDetEnq_Extension : PXGraphExtension<InventoryAllocDetEnq>
    {
        public static bool IsActive() => true;

        private readonly Dictionary<string, DateTime?> _dateCache
            = new Dictionary<string, DateTime?>(StringComparer.OrdinalIgnoreCase);

        /// <summary>
        /// RowSelected fires for each visible row in the inquiry grid.
        /// Populates the virtual UsrExpArrivalDate from the linked PO header.
        /// Uses generic event syntax (guaranteed to wire up for extension fields).
        /// </summary>
        protected void _(Events.RowSelected<InventoryAllocDetEnqResult> e)
        {
            if (e.Row == null || string.IsNullOrEmpty(e.Row.RefNbr)) return;

            string refNbr = e.Row.RefNbr.Trim();

            // Skip if already populated
            DateTime? current = (DateTime?)e.Cache.GetValue(e.Row, "UsrExpArrivalDate");
            if (current != null) return;

            DateTime? arrivalDate = LookupPOArrivalDate(refNbr);

            if (arrivalDate != null)
            {
                e.Cache.SetValue(e.Row, "UsrExpArrivalDate", arrivalDate);
            }
        }

        private DateTime? LookupPOArrivalDate(string refNbr)
        {
            if (_dateCache.TryGetValue(refNbr, out DateTime? cached))
                return cached;

            DateTime? arrivalDate = null;
            try
            {
                // Explicit column names — avoids BQL extension field resolution
                // issues that occur in foreign inquiry graphs
                using (PXDataRecord rec = PXDatabase.SelectSingle<PX.Objects.PO.POOrder>(
                    new PXDataField("UsrExpArrivalDate"),
                    new PXDataFieldValue("OrderNbr", refNbr)))
                {
                    arrivalDate = rec?.GetDateTime(0);
                }
            }
            catch (Exception ex)
            {
                PXTrace.WriteError(
                    $"IN402000 UsrExpArrivalDate lookup error for RefNbr={refNbr}: {ex.Message}");
            }

            _dateCache[refNbr] = arrivalDate;
            return arrivalDate;
        }
    }
}

using System;
using System.Collections.Generic;
using PX.Data;
using PX.Objects.PO;

namespace StudioB.Containers
{
    /// <summary>
    /// Propagates container Expected Arrival Date to linked PO headers and lines.
    /// Replaces IGCMPOLandedCostEntry_Extension (IIG dependency removed).
    /// Wire to ContainerEntry.Persist override when container DACs are built.
    /// </summary>
    public static class ContainerDatePropagation
    {
        /// <summary>
        /// Updates PO headers and lines with the container's expected arrival date.
        /// </summary>
        /// <param name="containerDate">The container's expected arrival date.</param>
        /// <param name="poRefs">List of (OrderType, OrderNbr, LineNbr) tuples from container lines.</param>
        public static void PropagateArrivalDate(
            DateTime? containerDate,
            List<Tuple<string, string, int?>> poRefs)
        {
            if (containerDate == null || poRefs == null || poRefs.Count == 0) return;

            HashSet<string> updatedHeaders = new HashSet<string>();

            foreach (var po in poRefs)
            {
                // Update PO Line
                if (po.Item3 != null)
                {
                    PXDatabase.Update<POLine>(
                        new PXDataFieldAssign<POLineExt.usrExpArrivalDate>(containerDate),
                        new PXDataFieldRestrict<POLine.orderType>(po.Item1),
                        new PXDataFieldRestrict<POLine.orderNbr>(po.Item2),
                        new PXDataFieldRestrict<POLine.lineNbr>(po.Item3)
                    );
                }

                // Update PO Header (once per unique PO)
                string headerKey = po.Item1 + ":" + po.Item2;
                if (!updatedHeaders.Contains(headerKey))
                {
                    PXDatabase.Update<POOrder>(
                        new PXDataFieldAssign<POOrderExt.usrExpArrivalDate>(containerDate),
                        new PXDataFieldRestrict<POOrder.orderType>(po.Item1),
                        new PXDataFieldRestrict<POOrder.orderNbr>(po.Item2)
                    );
                    updatedHeaders.Add(headerKey);
                }
            }
        }
    }
}

